    /** Checks if the given input contains a valid positive number and displays an error if it does not. */
    private static boolean validatePositiveNumber(EditText input, int emptyErrorRes, int invalidErrorRes) {
        CharSequence value = input.getText();

        if (TextUtils.isEmpty(value)) {
            input.setError(input.getContext().getString(emptyErrorRes));
            return false;
        }

        if (parsePositiveNumber(input, -1) <= 0) {
            input.setError(input.getContext().getString(invalidErrorRes));
            return false;
        }

        input.setError(null);
        return true;
    }

    /** Parses the content of the given input, returning the fallback if it is not a positive number. */
    private static int parsePositiveNumber(EditText input, int fallback) {
        try {
            int value = Integer.parseInt(input.getText().toString().trim());

            if (value > 0)
                return value;
        } catch (NumberFormatException e) {
            // Ignored, the fallback is returned below
        }

        return fallback;
    }
